def convert(odb_path, fields=("U", "S"), log=lambda s: None,
            cancel=lambda: False, progress=lambda s: None):
    """将 odb 转换为 FRD。

    参数:
      odb_path:  .odb 文件路径
      fields:    要导出的场列表(如 ["U", "S"])
      log:       子进程输出行回调
      cancel:    返回 True 时终止子进程(取消)
      progress:  阶段信息回调
    返回:
      生成的 .frd 完整路径
    异常:
      RuntimeError: 未找到 abaqus / 转换失败 / 已取消 / 未生成 frd
    """
    odb_path = os.path.abspath(odb_path)
    job_dir = os.path.dirname(odb_path)
    job_name = os.path.splitext(os.path.basename(odb_path))[0]
    frd = job_name + ".frd"
    mesh_inp = job_name + "_mesh.inp"

    # 文件名与场列表直接写入脚本参数区(执行时不传命令行参数)
    script = ODB2FRD_SCRIPT
    script = script.replace(
        'odb_name="thought-hole_STEP_000.odb"',
        'odb_name="' + job_name + '.odb"')
    script = script.replace(
        'out_frd="thought-hole_STEP_000.frd"',
        'out_frd="' + frd + '"')
    script = script.replace(
        'out_input="thought-hole_STEP_000.inp"',
        'out_input="' + mesh_inp + '"')
    field_list = ", ".join("'" + k + "'" for k in fields)
    script = script.replace(
        "export_fields = ['U', 'S']",
        "export_fields = [" + field_list + "]")

    script_path = os.path.join(job_dir, "odb2frd.py")
    with open(script_path, "w", encoding="utf-8") as f:
        f.write(script)
    progress("已写出转换脚本: " + script_path)

    cmd = "abaqus script=odb2frd.py"
    progress("执行: " + cmd)
    try:
        proc = subprocess.Popen(
            cmd, cwd=job_dir, shell=True,
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, encoding="utf-8", errors="replace")
    except OSError as exc:
        raise RuntimeError(
            "无法启动 abaqus 命令, 请确认已安装并在 PATH 中: " + str(exc))

    for line in proc.stdout:
        line = line.rstrip()
        if line:
            log(line)
        if cancel():
            proc.kill()
            proc.wait()
            raise RuntimeError("转换已被用户取消")
    proc.wait()
    if proc.returncode != 0:
        raise RuntimeError(
            "abaqus script 执行失败(返回码 %d), 请查看上述输出与 %s 下的日志"
            % (proc.returncode, job_dir))

    frd_path = os.path.join(job_dir, frd)
    if not os.path.exists(frd_path):
        raise RuntimeError("转换结束但未生成: " + frd_path)
    progress("FRD 转换完成: " + frd_path)
    return frd_path
